SINA_SMART["anat2-pelvic-vessels"] = {"lecture":"anat2-pelvic-vessels","title":"Pelvic vessels, lymphatics and autonomic nerves","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"anat2-pelvic-vessels:e0","text":"Aorta bifurcates at L4; common iliac divides at L5/S1.","topic":"Orientation","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-pelvic-vessels:e1","text":"External iliac → femoral; internal iliac → pelvis and perineum.","topic":"Orientation","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-pelvic-vessels:e2","text":"Internal iliac: ~4 cm; anterior (visceral) and posterior (parietal) divisions.","topic":"Internal iliac artery","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-pelvic-vessels:e3","text":"Anterior: superior vesical, inferior vesical/vaginal, uterine, middle rectal, obturator, internal pudendal, inferior gluteal.","topic":"Internal iliac artery","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-pelvic-vessels:e4","text":"Posterior: iliolumbar, lateral sacral, superior gluteal.","topic":"Internal iliac artery","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-pelvic-vessels:e5","text":"Uterine artery crosses over the ureter ('water under the bridge').","topic":"Internal iliac artery","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-pelvic-vessels:e6","text":"Internal pudendal: out via greater, back via lesser sciatic foramen.","topic":"Internal iliac artery","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-pelvic-vessels:e7","text":"Rectal venous plexus: superior → portal; middle/inferior → systemic.","topic":"Internal iliac artery","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-pelvic-vessels:e8","text":"Nodes: external iliac, internal iliac, obturator, presacral → common iliac.","topic":"Veins and lymphatics","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-pelvic-vessels:e10","text":"Parasympathetic S2-S4 (nervi erigentes): micturition, defecation, erection.","topic":"Autonomic nerves","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-pelvic-vessels:e11","text":"S2-S4 lesion → flaccid bladder; above S2 → spastic bladder.","topic":"Autonomic nerves","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-pelvic-vessels:e9","text":"Sympathetic T10-L2 → superior hypogastric → inferior hypogastric: storage, ejaculation.","topic":"Autonomic nerves","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"618can":"a","5jr3ke":"a","1hwfpw1":"a","k8rej9":"a","v7qrv1":"a","1qkow42":"a","12tm4d8":"a","1i916r8":"a","186kmla":"a","1n4dvm9":"a","1rwk9rb":"a","1iynzhz":"a","19cirsg":"a","1iiejga":"a"},"mapCounts":{"verified":0,"auto":14,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"anat2-pelvic-vessels:e0":{"s":0,"u":["Aorta bifurcates at L4; common iliac divides at L5/S1.","The aorta bifurcates at L4 (umbilicus, iliac crest level), giving the small median sacral artery; each common iliac artery divides at the sacroiliac joint ( L5/S1 ) into the external iliac (under the inguinal ligament → femoral artery) and the internal iliac (pelvis, perineum)."],"dp":[]},"anat2-pelvic-vessels:e1":{"s":0,"u":["External iliac → femoral; internal iliac → pelvis and perineum.","The aorta bifurcates at L4 (umbilicus, iliac crest level), giving the small median sacral artery; each common iliac artery divides at the sacroiliac joint ( L5/S1 ) into the external iliac (under the inguinal ligament → femoral artery) and the internal iliac (pelvis, perineum)."],"dp":[{"h":"Note","t":"Aorta bifurcates at L4 ; common iliac divides at the sacroiliac joint (L5/S1) into external iliac (→ femoral) and internal iliac (pelvis, perineum, gluteal region)."}]},"anat2-pelvic-vessels:e2":{"s":1,"u":["Internal iliac: ~4 cm; anterior (visceral) and posterior (parietal) divisions.","About 4 cm , divides into two divisions.","Posterior (parietal only) : iliolumbar , lateral sacral , superior gluteal ."],"dp":[]},"anat2-pelvic-vessels:e3":{"s":1,"u":["Anterior: superior vesical, inferior vesical/vaginal, uterine, middle rectal, obturator, internal pudendal, inferior gluteal.","Anterior (visceral + some parietal) : superior vesical (from the umbilical artery, which after birth obliterates into the medial umbilical ligament ; bladder dome, distal ureter); inferior vesical in males (bladder base, seminal vesicles, prostate) or vaginal in females; uterine artery , which runs medially in the base of the broad ligament and crosses over the ureter ('water under the bridge') to reach the cervix, then ascends tortuously; middle rectal (middle third of rectum; anastomoses with superior rectal from the IMA and inferior rectal from the pudendal); obturator (through the obturator canal to the medial thigh and hip); internal pudendal (leaves through the greater sciatic foramen , hooks around the ischial spine, re-enters through the lesser sciatic foramen : inferior rectal, perineal and penile/clitoral arteries); inferior gluteal .","Posterior (parietal only) : iliolumbar , lateral sacral , superior gluteal ."],"dp":[{"h":"Note","t":"Internal iliac : posterior division = iliolumbar, lateral sacral, superior gluteal (parietal only). Anterior = vesicals, uterine/vaginal, middle rectal, obturator, internal pudendal , inferior gluteal."}]},"anat2-pelvic-vessels:e4":{"s":1,"u":["Posterior: iliolumbar, lateral sacral, superior gluteal.","Posterior (parietal only) : iliolumbar , lateral sacral , superior gluteal ."],"dp":[]},"anat2-pelvic-vessels:e5":{"s":1,"u":["Uterine artery crosses over the ureter ('water under the bridge').","Anterior (visceral + some parietal) : superior vesical (from the umbilical artery, which after birth obliterates into the medial umbilical ligament ; bladder dome, distal ureter); inferior vesical in males (bladder base, seminal vesicles, prostate) or vaginal in females; uterine artery , which runs medially in the base of the broad ligament and crosses over the ureter ('water under the bridge') to reach the cervix, then ascends tortuously; middle rectal (middle third of rectum; anastomoses with superior rectal from the IMA and inferior rectal from the pudendal); obturator (through the obturator canal to the medial thigh and hip); internal pudendal (leaves through the greater sciatic foramen , hooks around the ischial spine, re-enters through the lesser sciatic foramen : inferior rectal, perineal and penile/clitoral arteries); inferior gluteal ."],"dp":[{"h":"Why hysterectomy can injure the ureter","t":"Near the cervix, the uterine artery passes over the ureter just before reaching the uterus, about 2 cm lateral to the cervix. When surgeons clamp the uterine vessels, the ureter lies directly beneath; a clamp placed too low or too lateral can crush or tie it. The memory aid 'water under the bridge' (ureter under artery) reminds surgeons to identify it first. Source: the lecture's uterine artery slide."},{"h":"Memory aid","t":"'Water under the bridge' : the ureter (water) passes under the uterine artery (bridge) near the cervix; the main site of ureteric injury in hysterectomy."}]},"anat2-pelvic-vessels:e6":{"s":1,"u":["Internal pudendal: out via greater, back via lesser sciatic foramen.","Anterior (visceral + some parietal) : superior vesical (from the umbilical artery, which after birth obliterates into the medial umbilical ligament ; bladder dome, distal ureter); inferior vesical in males (bladder base, seminal vesicles, prostate) or vaginal in females; uterine artery , which runs medially in the base of the broad ligament and crosses over the ureter ('water under the bridge') to reach the cervix, then ascends tortuously; middle rectal (middle third of rectum; anastomoses with superior rectal from the IMA and inferior rectal from the pudendal); obturator (through the obturator canal to the medial thigh and hip); internal pudendal (leaves through the greater sciatic foramen , hooks around the ischial spine, re-enters through the lesser sciatic foramen : inferior rectal, perineal and penile/clitoral arteries); inferior gluteal ."],"dp":[{"h":"Note","t":"Internal pudendal artery leaves the pelvis through the greater sciatic foramen, hooks round the ischial spine and enters the perineum through the lesser sciatic foramen (the pudendal nerve takes the same route)."}]},"anat2-pelvic-vessels:e7":{"s":1,"u":["Rectal venous plexus: superior → portal; middle/inferior → systemic.","Anterior (visceral + some parietal) : superior vesical (from the umbilical artery, which after birth obliterates into the medial umbilical ligament ; bladder dome, distal ureter); inferior vesical in males (bladder base, seminal vesicles, prostate) or vaginal in females; uterine artery , which runs medially in the base of the broad ligament and crosses over the ureter ('water under the bridge') to reach the cervix, then ascends tortuously; middle rectal (middle third of rectum; anastomoses with superior rectal from the IMA and inferior rectal from the pudendal); obturator (through the obturator canal to the medial thigh and hip); internal pudendal (leaves through the greater sciatic foramen , hooks around the ischial spine, re-enters through the lesser sciatic foramen : inferior rectal, perineal and penile/clitoral arteries); inferior gluteal ."],"dp":[]},"anat2-pelvic-vessels:e8":{"s":2,"u":["Nodes: external iliac, internal iliac, obturator, presacral → common iliac.","Lymph nodes : external iliac (bladder, prostate/cervix, lower limb via inguinal), internal iliac (all pelvic viscera, perineum), obturator (prostate, bladder neck, cervix: key for staging prostate and cervical cancer), presacral (rectum, posterior organs) → common iliac → para-aortic nodes.","The internal iliac vein joins the external iliac vein to form the common iliac vein at L5/S1; the left common iliac vein is longer and crosses under the right common iliac artery (compression can cause left-sided DVT)."],"dp":[{"h":"Clinical","t":"Rectal veins : superior → IMV → portal ; middle and inferior → internal iliac → systemic : a portosystemic anastomosis. Left common iliac vein is compressed by the right common iliac artery → left-sided DVT (May-Thurner)."},{"h":"Note","t":"Nodes: obturator (prostate, cervix staging), internal and external iliac, presacral → common iliac → para-aortic."}]},"anat2-pelvic-vessels:e10":{"s":3,"u":["Parasympathetic S2-S4 (nervi erigentes): micturition, defecation, erection.","Parasympathetic : pelvic splanchnic nerves (nervi erigentes), S2-S4 , leave via the anterior sacral foramina to join the inferior hypogastric plexus.","Functions: emptying and erection : detrusor contraction (micturition), rectal contraction (defecation), vasodilation, glandular secretion."],"dp":[{"h":"Note","t":"Sympathetic (T10-L2) via the hypogastric plexuses = storage and ejaculation . Parasympathetic S2-S4 (nervi erigentes) = voiding, defecation, erection ('point and shoot')."}]},"anat2-pelvic-vessels:e11":{"s":3,"u":["S2-S4 lesion → flaccid bladder; above S2 → spastic bladder.","Lesions above S2 give a spastic bladder; lesions of S2-S4 give a flaccid bladder with overflow incontinence."],"dp":[{"h":"Clinical","t":"Lesion above S2 → spastic (reflex) bladder ; lesion of S2-S4/cauda equina → flaccid bladder with overflow incontinence. Rectal or pelvic surgery can damage the plexuses → retention and erectile dysfunction."}]},"anat2-pelvic-vessels:e9":{"s":3,"u":["Sympathetic T10-L2 → superior hypogastric → inferior hypogastric: storage, ejaculation.","Sympathetic (T10-L2): lumbar splanchnics → inferior mesenteric ganglion → superior hypogastric plexus (in front of L5/S1, between the common iliac arteries, purely sympathetic) → right and left hypogastric nerves → inferior hypogastric (pelvic) plexus .","Functions: storage and ejaculation : relaxes the detrusor, closes the bladder neck, contracts the internal anal sphincter, vasoconstriction."],"dp":[]}},"meta":{"618can":{"a":"recall","vg":"anat2-pelvic-vessels:e0/recall/1"},"5jr3ke":{"a":"recall","vg":"anat2-pelvic-vessels:e1/recall/1"},"1hwfpw1":{"a":"recall","vg":"anat2-pelvic-vessels:e2/recall/1"},"k8rej9":{"a":"recall","vg":"anat2-pelvic-vessels:e5/recall/1"},"v7qrv1":{"a":"recall","vg":"anat2-pelvic-vessels:e5/recall/2"},"1qkow42":{"a":"recall","vg":"anat2-pelvic-vessels:e6/recall/1"},"12tm4d8":{"a":"recall","vg":"anat2-pelvic-vessels:e7/recall/1"},"1i916r8":{"a":"recall","vg":"anat2-pelvic-vessels:e7/recall/2"},"186kmla":{"a":"recall","vg":"anat2-pelvic-vessels:e8/recall/1"},"1n4dvm9":{"a":"recall","vg":"anat2-pelvic-vessels:e9/recall/1"},"1rwk9rb":{"a":"recall","vg":"anat2-pelvic-vessels:e10/recall/1"},"1iynzhz":{"a":"recall","vg":"anat2-pelvic-vessels:e10/recall/2"},"19cirsg":{"a":"recall","vg":"anat2-pelvic-vessels:e9/recall/2"},"1iiejga":{"a":"recall","vg":"anat2-pelvic-vessels:e11/recall/1"}},"explRev":"14f53a9824bf"};
